package wasidremin.gmccpa.match

import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/**
 * Built-in templates are generated by the SAME ScreenModel.cutTemplate the app uses, from the
 * real Equinox captures in test resources. REGEN_VISION=1 rewrites the assets; otherwise the
 * test fails if the committed assets differ from what the captures produce.
 */
class BuiltInTemplatesTest {
    private data class Spec(val capture: String, val kind: ScreenModel.Kind, val role: String,
                            val nx: Float, val ny: Float)

    private val specs = listOf(
        Spec("cap2_home_grid.png", ScreenModel.Kind.STRIP, "maps", 0.029f, 0.331f),
        Spec("cap2_home_grid.png", ScreenModel.Kind.STRIP, "spotify", 0.029f, 0.441f),
        Spec("cap2_home_grid.png", ScreenModel.Kind.STRIP, "phone", 0.029f, 0.555f),
        Spec("cap2_home_grid.png", ScreenModel.Kind.GRID, "phone", 0.186f, 0.232f),
        Spec("cap2_home_grid.png", ScreenModel.Kind.GRID, "music", 0.351f, 0.232f),
        Spec("cap2_home_grid.png", ScreenModel.Kind.GRID, "maps", 0.517f, 0.232f),
        Spec("cap2_home_grid.png", ScreenModel.Kind.GRID, "spotify", 0.848f, 0.232f),
        Spec("cap2_home_grid.png", ScreenModel.Kind.GLYPH, "other", 0.029f, 0.915f),
        Spec("cap3_dashboard.png", ScreenModel.Kind.GLYPH, "dashboard", 0.029f, 0.915f),
    )

    private val assetDir = File("src/main/assets/" + IconTemplateStore.BUILTIN_ASSET_DIR)

    private fun generated(): Map<String, String> {
        val frames = specs.map { it.capture }.distinct().associateWith { ScreenModelTest.loadForTest(it) }
        return specs.associate { s ->
            val t = ScreenModel.cutTemplate(frames.getValue(s.capture), s.kind, s.role, s.nx, s.ny,
                sourceCaptureId = s.capture.removeSuffix(".png"), createdIso = null)
            t.name to t.toJson().toString(2)
        }
    }

    @Test fun assetsMatchCaptures() {
        val gen = generated()
        if (System.getenv("REGEN_VISION") == "1") {
            assetDir.mkdirs()
            gen.forEach { (name, json) -> File(assetDir, "$name.json").writeText(json + "\n") }
        }
        assertEquals(9, gen.size)
        for ((name, json) in gen) {
            val f = File(assetDir, "$name.json")
            assertTrue("missing asset ${f.path} — run with REGEN_VISION=1", f.isFile)
            assertEquals("asset $name is stale — run with REGEN_VISION=1",
                JSONObject(json).toString(), JSONObject(f.readText()).toString())
        }
    }

    @Test fun builtInsRecogniseTheirOwnFrames() {
        val home = ScreenModelTest.loadForTest("cap2_home_grid.png")
        val dash = ScreenModelTest.loadForTest("cap3_dashboard.png")
        val t = generated().mapValues { IconMatcher.IconTemplate.fromJson(JSONObject(it.value)) }
        for (role in listOf("maps", "spotify", "phone")) {
            val hit = ScreenModel.find(dash, t.getValue("strip.$role"), ScreenModel.REFERENCE.stripRoi, 1)
            assertTrue("strip.$role on dashboard ${hit.score}", hit.passed)
        }
        assertEquals(ScreenModel.Surface.DASHBOARD,
            ScreenModel.surface(dash, t["glyph.dashboard"], t["glyph.other"]))
        assertEquals(ScreenModel.Surface.NOT_DASHBOARD,
            ScreenModel.surface(home, t["glyph.dashboard"], t["glyph.other"]))
    }
}
